CREATE OR ALTER TRIGGER dbo.trg_admission_capacity_guard ON dbo.admissions INSTEAD OF INSERT AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.wards w ON w.WardID=i.WardID GROUP BY w.WardID,w.BedCapacity HAVING (SELECT COUNT(*) FROM dbo.admissions a WHERE a.WardID=w.WardID AND a.WardStatus='Admitted')+COUNT(*)>w.BedCapacity) THROW 51021,'Admission blocked: ward capacity would be exceeded.',1; INSERT dbo.admissions(AdmissionID,PatientName,WardID,WardStatus,AdmissionDate) SELECT AdmissionID,PatientName,WardID,WardStatus,AdmissionDate FROM inserted; END;
GO
CREATE OR ALTER TRIGGER dbo.trg_admission_audit ON dbo.admissions AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON; INSERT dbo.admission_audit(AdmissionID,ActionName,PatientName,WardID,WardStatus,ChangedBy) SELECT i.AdmissionID,'INSERT',i.PatientName,i.WardID,i.WardStatus,ORIGINAL_LOGIN() FROM inserted i LEFT JOIN deleted d ON d.AdmissionID=i.AdmissionID WHERE d.AdmissionID IS NULL; INSERT dbo.admission_audit(AdmissionID,ActionName,PatientName,WardID,WardStatus,ChangedBy) SELECT d.AdmissionID,'DELETE',d.PatientName,d.WardID,d.WardStatus,ORIGINAL_LOGIN() FROM deleted d LEFT JOIN inserted i ON i.AdmissionID=d.AdmissionID WHERE i.AdmissionID IS NULL; INSERT dbo.admission_audit(AdmissionID,ActionName,PatientName,WardID,WardStatus,ChangedBy) SELECT i.AdmissionID,'UPDATE',i.PatientName,i.WardID,i.WardStatus,ORIGINAL_LOGIN() FROM inserted i JOIN deleted d ON d.AdmissionID=i.AdmissionID; END;